Source code in <code>pycodeloop/core/tools/search.py</code> <pre><code>def run(self, pattern: str, path: str = ".", max_results: int = 100) -&gt; ToolResult:
    try:
        regex = re.compile(pattern)
    except re.error as exc:
        return ToolResult(output=f"Invalid regex: {exc}", is_error=True)

    matches: list[str] = []
    for file_path in Path(path).rglob("*"):
        if not file_path.is_file() or set(file_path.parts) &amp; _SKIP_DIRS:
            continue
        try:
            text = file_path.read_text(errors="ignore")
        except OSError:
            continue
        for lineno, line in enumerate(text.splitlines(), start=1):
            if regex.search(line):
                matches.append(f"{file_path}:{lineno}: {line.strip()}")
                if len(matches) &gt;= max_results:
                    return ToolResult(output=truncate("\n".join(matches)))

    return ToolResult(
        output=truncate("\n".join(matches)) if matches else "No matches."
    )
</code></pre>

Source code in <code>pycodeloop/core/tools/bash.py</code> <pre><code>def run(self, command: str, timeout: int = 120) -&gt; ToolResult:
    try:
        proc = subprocess.run(
            command,
            shell=True,
            capture_output=True,
            text=True,
            timeout=timeout,
        )
    except subprocess.TimeoutExpired:
        return ToolResult(
            output=f"Command timed out after {timeout}s", is_error=True
        )

    output = truncate(proc.stdout + proc.stderr)

    return ToolResult(output=output, is_error=proc.returncode != 0)
